"use client"
import { useId } from "react"
import { Area, AreaChart, CartesianGrid, ResponsiveContainer, Tooltip, XAxis, YAxis } from "recharts"
export type PlotDatum = { label: string; value: number; previous?: number }
export type PlotLineChartProps = { data: PlotDatum[]; label?: string; compact?: boolean; area?: boolean; loading?: boolean; error?: string }
export function PlotLineChart({ data, label = "Demo activity", compact = false, area = true, loading = false, error }: PlotLineChartProps) {
  const id = useId().replace(/:/g, "")
  if (loading) return <div className="chart-fallback" role="status">Loading visualization…</div>
  if (error) return <div className="chart-fallback" role="alert">{error}</div>
  const valid = data.filter(d => Number.isFinite(d.value) && (d.previous === undefined || Number.isFinite(d.previous)))
  if (!valid.length) return <div className="chart-fallback" role="status">No data available for this period.</div>
  return <div className={`plot-line-chart ${compact ? "is-compact" : ""}`} role="group" aria-label={label} style={{ width: "100%", height: "100%", minHeight: compact ? 100 : 180, overflow: "hidden" }}>
    <ResponsiveContainer width="100%" height="100%" minWidth={0} initialDimension={{ width: 560, height: 260 }}><AreaChart data={valid} margin={{ top: 16, right: 16, left: compact ? -10 : -20, bottom: compact ? 4 : 0 }}>
    <defs><linearGradient id={id} x1="0" y1="0" x2="0" y2="1"><stop offset="0%" stopColor="currentColor" stopOpacity={area ? 0.16 : 0} /><stop offset="100%" stopColor="currentColor" stopOpacity="0" /></linearGradient></defs>
    <CartesianGrid vertical={false} stroke="var(--plot-grid, #27272a)" strokeDasharray="3 5" />
    <XAxis dataKey="label" axisLine={false} tickLine={false} minTickGap={compact ? 32 : 42} hide={compact} tick={{ fill: "var(--plot-muted, #a1a1aa)", fontSize: 11 }} tickMargin={12} />
    <YAxis axisLine={false} tickLine={false} hide={compact} tick={{ fill: "var(--plot-muted, #a1a1aa)", fontSize: 11 }} tickFormatter={value => `${value / 1000}k`} tickCount={4} domain={[0, (dataMax: number) => Math.ceil(dataMax * 1.15)]} />
    <Tooltip cursor={{ stroke: "var(--plot-muted, #71717a)", strokeDasharray: "3 3" }} contentStyle={{ background: "var(--plot-surface, #18181b)", border: "1px solid var(--plot-grid, #3f3f46)", borderRadius: 8, color: "var(--plot-ink, #fafafa)", fontSize: 12 }} />
    {valid.some(d => d.previous !== undefined) && <Area type="monotone" dataKey="previous" name="Previous period" stroke="var(--plot-muted, #71717a)" strokeDasharray="4 5" fill="none" strokeWidth={1.5} isAnimationActive={false} />}
    <Area type="monotone" dataKey="value" name={label} stroke="currentColor" strokeWidth={2} fill={`url(#${id})`} activeDot={{ r: 5, stroke: "var(--plot-surface, #09090b)", strokeWidth: 3 }} isAnimationActive={false} />
    </AreaChart></ResponsiveContainer><span className="sr-only">Sample data. {valid.map(d => `${d.label}: ${d.value}`).join("; ")}. Use left and right arrow keys on the chart to inspect values.</span></div>
}
